<style>
:root{--bds-green:#84c441;--bds-orange:#ff6b22;--bds-ink:#171c26;--bds-muted:#8b9099;--bds-soft:#f4f6f8;--bds-line:#e7e9ec;--bds-navy:#26354b}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--bds-ink);font-family:"Be Vietnam Pro",sans-serif;background:#fff}.bds-page a{color:inherit;text-decoration:none}.bds-container{width:min(1180px,calc(100% - 40px));margin:auto}.bds-header{position:absolute;z-index:20;top:0;left:0;right:0;color:#fff;background:linear-gradient(180deg,rgba(10,24,39,.42),transparent)}.bds-nav{height:96px;display:flex;align-items:center;justify-content:space-between}.bds-logo{display:flex;align-items:center;gap:10px;color:#fff}.bds-logo-mark{font-size:39px;color:var(--bds-green);transform:rotate(-3deg)}.bds-logo strong{font:700 24px Montserrat,sans-serif;display:block;line-height:.9}.bds-logo small{font-size:17px}.bds-nav nav{display:flex;align-items:center;gap:42px;font-weight:600}.bds-nav nav a:hover,.bds-nav nav a:first-child{color:var(--bds-green)}.bds-menu-toggle{display:none;border:0;background:none;color:#fff;font-size:24px}.bds-hero{min-height:720px;color:#fff;background-position:center;background-size:cover;position:relative;display:flex;align-items:center}.bds-hero:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(20,27,38,.52),rgba(20,45,67,.2))}.bds-hero-content{position:relative;z-index:2;padding-top:100px;text-align:center}.bds-hero h1{font:500 clamp(42px,5vw,72px) Montserrat,sans-serif;margin:30px 0 70px}.bds-search{display:grid;grid-template-columns:170px 1fr auto 250px;background:#fff;color:var(--bds-ink);min-height:66px;box-shadow:0 14px 40px rgba(0,0,0,.16)}.bds-search select,.bds-search input{border:0;padding:0 24px;font:inherit;outline:none;background:#fff}.bds-search select{background:var(--bds-orange);color:#fff;font-weight:600}.bds-search-more{display:flex;align-items:center;padding:0 24px;border-left:1px solid var(--bds-line);white-space:nowrap}.bds-search button{border:7px solid #fff;background:var(--bds-green);color:#fff;font-weight:700;text-transform:uppercase;padding:0 28px;font:700 15px inherit}.bds-quick-label{margin:34px 0 18px}.bds-type-shortcuts{display:flex;justify-content:center;gap:16px;flex-wrap:wrap}.bds-type-shortcuts a{width:120px;padding:24px 12px 13px;background:rgba(17,24,31,.48);border:1px solid rgba(255,255,255,.16);transition:.25s}.bds-type-shortcuts a:hover{background:var(--bds-green);transform:translateY(-4px)}.bds-type-shortcuts i{font-size:35px;display:block;margin-bottom:13px}.bds-section{padding:88px 0}.bds-section.soft{background:var(--bds-soft)}.bds-heading{display:flex;justify-content:space-between;align-items:end;margin-bottom:42px}.bds-heading h2{font:500 clamp(30px,3vw,42px) Montserrat,sans-serif;margin:0;text-transform:uppercase}.bds-heading h2 em{color:var(--bds-orange);font-style:normal}.bds-heading p{color:var(--bds-muted);margin:10px 0 0}.bds-tabs{display:flex;gap:0}.bds-tabs a{padding:8px 20px;border-right:1px solid var(--bds-line);font-weight:600}.bds-tabs a:hover,.bds-tabs a:first-child{color:var(--bds-orange)}.bds-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.bds-property-card{background:#fff;box-shadow:0 12px 30px rgba(24,33,44,.06);overflow:hidden;transition:.25s}.bds-property-card:hover{transform:translateY(-5px);box-shadow:0 16px 40px rgba(24,33,44,.12)}.bds-property-media{display:block;position:relative;aspect-ratio:1.48;overflow:hidden}.bds-property-media img{width:100%;height:100%;object-fit:cover;transition:.4s}.bds-property-card:hover img{transform:scale(1.04)}.bds-status,.bds-hot{position:absolute;top:18px;left:18px;border-radius:18px;padding:6px 18px;color:#fff;background:#4b79aa;font-size:13px}.bds-status.rent{background:var(--bds-orange)}.bds-hot{left:92px;background:#f14b57}.bds-tour{position:absolute;inset:50% auto auto 50%;transform:translate(-50%,-50%);border:2px solid #fff;border-radius:50%;padding:14px 8px;color:#fff;font-weight:700;background:rgba(0,0,0,.2)}.bds-property-body{padding:20px 20px 16px}.bds-property-body h3{font-size:18px;margin:0 0 12px}.bds-location{color:#969ba2;font-size:14px}.bds-location i{color:var(--bds-green);margin-right:8px}.bds-price{color:var(--bds-orange);font-size:20px;margin-bottom:0}.bds-price i{font-size:14px;color:#aeb3b8;background:#f6f6f6;padding:12px;margin-right:10px}.bds-price small{font-size:13px;color:var(--bds-ink)}.bds-property-specs{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--bds-line);color:#999}.bds-property-specs span{padding:15px 8px;text-align:center;border-right:1px solid var(--bds-line);font-size:13px}.bds-property-specs i{margin-right:5px;color:#d7dadd}.bds-mosaic{display:grid;grid-template-columns:1fr 1fr 1fr;grid-template-rows:280px 280px;gap:18px}.bds-mosaic a{position:relative;overflow:hidden}.bds-mosaic a:first-child{grid-column:span 2}.bds-mosaic img{width:100%;height:100%;object-fit:cover;transition:.45s}.bds-mosaic a:hover img{transform:scale(1.05)}.bds-mosaic span{position:absolute;inset:auto 0 25px;text-align:center;color:#fff;font:700 30px Montserrat;text-shadow:0 2px 8px #000}.bds-mosaic small{display:block;font:400 14px "Be Vietnam Pro"}.bds-news-feature{display:grid;grid-template-columns:1.05fr 1fr;gap:30px}.bds-lead-news{border:1px solid var(--bds-line)}.bds-lead-news img{width:100%;height:360px;object-fit:cover}.bds-lead-news div{padding:22px}.bds-lead-news h3{font-size:22px;margin:14px 0}.bds-meta{font-size:13px;color:#737983}.bds-news-list article{display:grid;grid-template-columns:145px 1fr;gap:18px;padding:0 0 20px;margin-bottom:20px;border-bottom:1px solid var(--bds-line)}.bds-news-list img{width:145px;height:86px;object-fit:cover}.bds-news-list h3{font-size:16px;margin:0 0 14px}.bds-news-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:26px}.bds-news-card{border:1px solid var(--bds-line);background:#fff}.bds-news-card img{width:100%;height:220px;object-fit:cover}.bds-news-card div{padding:20px}.bds-news-card h3{font-size:19px;line-height:1.5}.bds-newsletter{padding:70px 0;background-position:center;background-size:cover}.bds-newsletter-card{background:#fff;border-radius:18px;padding:45px;display:grid;grid-template-columns:1fr 1.15fr;align-items:center;gap:40px}.bds-newsletter h2{font:700 34px Montserrat;margin:0 0 8px}.bds-newsletter p{color:#9a9fa5}.bds-newsletter form{display:flex;background:#fafafa;border-radius:40px;padding:6px 7px 6px 24px;box-shadow:0 8px 30px rgba(0,0,0,.08)}.bds-newsletter input{flex:1;border:0;background:none;outline:0;font:inherit}.bds-newsletter button{border:0;border-radius:30px;background:var(--bds-green);color:#fff;font-weight:700;padding:16px 28px}.bds-footer{position:relative;background:#25282b;color:#aeb2b5;padding:78px 0 60px}.bds-footer-grid{display:grid;grid-template-columns:1.25fr .8fr 1fr .7fr;gap:58px}.bds-footer h3{color:#fff;text-transform:uppercase;font-size:15px;padding-bottom:20px;border-bottom:1px solid #46494c}.bds-footer h3:after{content:"";display:block;width:45px;border-bottom:1px solid var(--bds-orange);position:relative;top:21px}.bds-footer a{display:block;margin:13px 0}.bds-footer strong{font-size:25px;color:var(--bds-orange)}.bds-to-top{position:absolute;right:30px;bottom:30px;width:52px;height:52px;border-radius:50%;display:grid!important;place-items:center;background:var(--bds-green);color:#fff!important}.bds-inner-hero{padding:150px 0 60px;background:var(--bds-navy);color:#fff}.bds-filter-bar{padding:25px;background:#fff;box-shadow:0 12px 35px rgba(30,40,50,.09);margin:-30px auto 45px;position:relative}.bds-filter-bar form{display:grid;grid-template-columns:2fr repeat(3,1fr) auto;gap:12px}.bds-filter-bar input,.bds-filter-bar select{padding:13px;border:1px solid var(--bds-line)}.bds-btn{border:0;background:var(--bds-green);color:#fff;padding:13px 22px;font-weight:700}.bds-detail{display:grid;grid-template-columns:1.4fr .8fr;gap:35px}.bds-gallery-main{height:520px;width:100%;object-fit:cover}.bds-thumbs{display:flex;gap:10px;margin-top:10px;overflow:auto}.bds-thumbs button{border:2px solid transparent;padding:0;background:none}.bds-thumbs img{width:110px;height:72px;object-fit:cover}.bds-thumbs button.is-active{border-color:var(--bds-orange)}.bds-summary-card{padding:30px;background:#fff;box-shadow:0 10px 35px rgba(30,40,50,.1);position:sticky;top:20px}.bds-summary-card h1{font:700 30px Montserrat}.bds-detail-price{color:var(--bds-orange);font-size:27px}.bds-facts{display:grid;grid-template-columns:1fr 1fr;gap:12px}.bds-facts span{padding:12px;background:var(--bds-soft)}.bds-content-card{margin-top:35px;padding:34px;background:#fff;border:1px solid var(--bds-line);line-height:1.8}.xd-landing-block{position:relative}.xd-edit-block{position:absolute!important;z-index:12;top:14px;right:14px;border:0;border-radius:24px;background:#e5242a;color:#fff;padding:11px 18px;font-weight:700}
@media(max-width:900px){.bds-nav nav{display:none;position:absolute;top:80px;left:20px;right:20px;padding:22px;background:#1f2d40;flex-direction:column;align-items:flex-start;gap:18px}.bds-nav nav.is-open{display:flex}.bds-menu-toggle{display:block}.bds-search{grid-template-columns:1fr}.bds-search>*{min-height:56px}.bds-grid,.bds-news-grid{grid-template-columns:1fr 1fr}.bds-news-feature,.bds-newsletter-card,.bds-detail{grid-template-columns:1fr}.bds-mosaic{grid-template-columns:1fr 1fr}.bds-mosaic a:first-child{grid-column:span 2}.bds-footer-grid{grid-template-columns:1fr 1fr}.bds-filter-bar form{grid-template-columns:1fr 1fr}.bds-gallery-main{height:400px}}
@media(max-width:620px){.bds-container{width:min(100% - 24px,1180px)}.bds-hero{min-height:760px}.bds-hero h1{font-size:38px;margin:35px 0}.bds-grid,.bds-news-grid,.bds-footer-grid{grid-template-columns:1fr}.bds-heading{display:block}.bds-tabs{overflow:auto;margin-top:20px}.bds-mosaic{display:block}.bds-mosaic a{display:block;height:260px;margin-bottom:12px}.bds-news-feature{display:block}.bds-news-list{margin-top:30px}.bds-newsletter-card{padding:28px}.bds-newsletter form{display:block;border-radius:16px;padding:14px}.bds-newsletter input{width:100%;padding:10px}.bds-newsletter button{width:100%;margin-top:8px}.bds-filter-bar form{grid-template-columns:1fr}}
.bds-logo img{display:block;width:auto;max-width:190px;height:64px;object-fit:contain}
.bds-topbar{border-bottom:1px solid rgba(255,255,255,.18);background:rgba(12,25,38,.3);font-size:13px}.bds-topbar-inner{display:flex;min-height:38px;align-items:center;justify-content:space-between;gap:20px}.bds-topbar-contact,.bds-topbar-account{display:flex;align-items:center;gap:16px}.bds-topbar-contact a,.bds-topbar-account a{display:inline-flex;align-items:center;gap:7px}.bds-topbar a:hover{color:var(--bds-green)}.bds-topbar-account form{margin:0}.bds-topbar-account button{border:0;padding:0;background:none;color:inherit;font:inherit;cursor:pointer}.bds-topbar-account button:hover{color:var(--bds-green)}
@media(max-width:620px){.bds-topbar-contact a:nth-child(2){display:none}.bds-topbar-inner{min-height:36px}.bds-topbar-contact,.bds-topbar-account{gap:9px}.bds-logo img{max-width:145px;height:54px}}
</style>
